import{_ as e,a,c as r,ac as d}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"百年孤独","description":"以布恩迪亚家族与马孔多为线索，按二十章阅读命名、记忆、战争与孤独。","frontmatter":{"title":"百年孤独","description":"以布恩迪亚家族与马孔多为线索，按二十章阅读命名、记忆、战争与孤独。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 文学与人文社科 · 中外文学经典","summary":"以布恩迪亚家族与马孔多为线索，按二十章阅读命名、记忆、战争与孤独。","status":"active","related":[{"title":"杀死一只知更鸟","link":"/life/personal/books/humanities/to-kill-a-mockingbird","kind":"书籍导读","scope":"general","audience":"general"},{"title":"一句顶一万句","link":"/life/personal/books/humanities/one-sentence-ten-thousand","kind":"书籍导读","scope":"general","audience":"general"}],"prev":false,"next":{"text":"杀死一只知更鸟","link":"/life/personal/books/humanities/to-kill-a-mockingbird"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"杀死一只知更鸟","link":"/life/personal/books/humanities/to-kill-a-mockingbird"}},"headers":[],"relativePath":"life/personal/books/humanities/one-hundred-years-of-solitude.md","filePath":"life/personal/books/humanities/one-hundred-years-of-solitude.md"}'),o={name:"life/personal/books/humanities/one-hundred-years-of-solitude.md"};function n(i,t,l,s,h,p){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="百年孤独" tabindex="-1">百年孤独 <a class="header-anchor" href="#百年孤独" aria-label="Permalink to &quot;百年孤独&quot;">​</a></h1><p><strong>分类：文学与人文社科 → 中外文学经典。</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>加西亚·马尔克斯将布恩迪亚家族数代人的命运与马孔多的兴衰交织起来。发明与发现、内战、商业扩张、家族关系和私人欲望共同进入叙事，奇异事件与日常生活经常以同样平静的语气呈现。</p><p>阅读难点不只在人物多，还在名字与行为模式反复出现。建议记录人物的父母、配偶和时代位置，避免只凭“奥雷里亚诺”或“何塞·阿尔卡蒂奥”辨认人物。重复并不意味着每代人的选择完全相同，它也展示记忆如何被继承、误读或遗忘。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p><strong>《百年孤独》：作者为加夫列尔·加西亚·马尔克斯（Gabriel García Márquez）。</strong> 他是哥伦比亚小说家和记者，获1982年诺贝尔文学奖。<a href="https://www.cervantes.es/bibliotecas_documentacion_espanol/creadores/garcia_marquez_gabriel.htm" target="_blank" rel="noopener noreferrer">塞万提斯学院作家档案</a>可核对创作背景；<a href="https://www.gabrielgarciamarquezfundacion.com/el-premio-nobel" target="_blank" rel="noopener noreferrer">马尔克斯基金会</a>可核对获奖信息。文学地位说明作品的叙事影响，不意味着小说可直接作为历史事实记录。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合愿意接受人物众多、时间跳跃与奇异叙事的长篇小说读者，尤其适合关注家族记忆和拉丁美洲文学的人。初读可边读边画简图，不必开头就记住全部名字；书中战争与家庭暴力内容宜提前了解。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>原著 <em>Cien años de soledad</em> 于 1967 年出版。通行文本有 20 个没有独立章名的章节；下表编号用于定位，<strong>小标题为本站拟定</strong>。中文版译者、人物译名和页码尚待实物核对，不把某一译本的语言当作唯一文本。</p><div class="warning custom-block"><p class="custom-block-title">剧透提示</p><p>下表覆盖全书及家族与马孔多的结局。初读时可逐章查看。</p></div><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>本站概括与阅读重点</th></tr></thead><tbody><tr><td>1 · 冰与新奇事物</td><td>从未来的回忆切入村镇早期生活，吉卜赛人带来器物与知识。家族创始人对发现的热情，也逐渐与日常生活拉开距离。</td></tr><tr><td>2 · 建村与出走</td><td>回叙婚姻、旧日冲突和迁徙，解释马孔多的建立；下一代的欲望与出走让家庭面对无法完全控制的变化。</td></tr><tr><td>3 · 失眠与遗忘</td><td>丽贝卡进入家庭，失眠和失忆侵入村镇。给物品贴标签的做法，把记住名称与理解世界之间的距离具体化。</td></tr><tr><td>4 · 爱情与失序</td><td>年轻人的婚恋、期待和竞争展开，家族创始人的精神世界也越来越难被旁人理解。亲密关系与孤立可以同时存在。</td></tr><tr><td>5 · 家庭与战争</td><td>婚姻、死亡与政治冲突交织，奥雷里亚诺走向战争。私人生活与公共政治不再能够清楚分开。</td></tr><tr><td>6 · 家门口的权力</td><td>阿尔卡蒂奥掌权及其结局，展示权力如何迅速脱离约束。关注他对出身、承认和控制的渴望。</td></tr><tr><td>7 · 生还与死亡</td><td>上校的处境再次逆转，家族经历死亡与离散。流动的血与异常自然现象，把私人哀痛写进村镇。</td></tr><tr><td>8 · 无法安放的欲望</td><td>奥雷里亚诺·何塞的感情与战争经历交织。反复出现的名字和欲望，成为理解家族命运的线索。</td></tr><tr><td>9 · 战争的耗损</td><td>上校越来越远离最初的信念，和平也不能简单恢复意义。区分战争胜负、政治结果与人的精神代价。</td></tr><tr><td>10 · 双胞胎与繁盛</td><td>何塞·阿尔卡蒂奥第二和奥雷里亚诺第二进入叙事中心，佩特拉及费尔南达带来新的家庭关系，繁盛与欲望相伴。</td></tr><tr><td>11 · 外来的秩序</td><td>费尔南达的生活习惯与家族发生摩擦，上校的儿子们陆续出现，铁路等新事物将马孔多与外界紧密连接。</td></tr><tr><td>12 · 香蕉公司的世界</td><td>外来商业改变小镇，美人儿蕾梅黛丝的离去与针对上校儿子的暴力形成对照。旧经验难以解释新的社会关系。</td></tr><tr><td>13 · 衰老中的维持</td><td>乌尔苏拉继续维持家庭，后代的教育与生活各有安排；上校走向生命终点。维持日常秩序需要怎样的劳动？</td></tr><tr><td>14 · 被封锁的爱情</td><td>梅梅与毛里西奥·巴比伦的关系受到阻断，家庭用控制和隐瞒处理不愿承认的事实；阿玛兰妲也走向生命终点。</td></tr><tr><td>15 · 屠杀与否认</td><td>香蕉工人的冲突导致暴力，幸存者的记忆却遭到官方叙述否认。没有被承认，并不等于从未发生。</td></tr><tr><td>16 · 漫长的雨</td><td>持续降雨侵蚀财富、房屋与生活。时间不只由事件推进，也以等待、消耗和重复呈现。</td></tr><tr><td>17 · 雨后的衰败</td><td>家族在衰老和匮乏中继续生活，乌尔苏拉和双胞胎相继离世。过去的繁荣无法自动成为后人的支撑。</td></tr><tr><td>18 · 房屋与手稿</td><td>剩下的人各自守着秘密或记忆，奥雷里亚诺越来越接近梅尔基亚德斯的手稿。阅读与现实的关系逐渐收拢。</td></tr><tr><td>19 · 归来的阿玛兰妲·乌尔苏拉</td><td>她带着新的生活想象回到马孔多，却面对衰败；奥雷里亚诺的社交、阅读和爱情发生在越来越空旷的世界里。</td></tr><tr><td>20 · 读懂结局</td><td>爱情、生育、死亡与手稿解释汇合，家族的最后一代和马孔多走向终结。此时可以重读开篇的时间结构与预兆。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p><strong>本站阅读评析，并非书单提供者的个人阅读经历。</strong> 孤独并不只是独处：有人身处庞大家庭却无法交流，有人拥有权力却失去信念，也有人坚持记忆却得不到承认。它既是私人感受，也是关系与历史共同造成的处境。</p><p>反复的名字要求读者辨认相似背后的差别。若只把全书理解为命运循环，容易忽略各代人面对的政治、经济与家庭条件已经改变。面对战争与屠杀，尤其不能让奇异的叙事方式遮住现实的暴力。</p><p>读后笔记可以分两栏：谁记住了什么，谁有权决定什么被承认。将失眠、家族秘密、屠杀后的否认和手稿放在一起，会形成比单记人物关系更深入的线索。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><p><strong>本站原创阅读提炼，不是原书引用：</strong> 名字会重现，处境却已改变；辨认差异，才能看见循环如何形成。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p><strong>本站阅读评析，非书单提供者亲历：</strong> 按代际画人物图，另建记忆与否认索引：谁记住、隐瞒或否认事件，谁能反驳，结果怎样。将失眠、家庭秘密与香蕉工人事件并读，练习区分叙述手法、人物经验和社会权力。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>密集叙事与意象让重读有层次，也增加初读辨认成本；只背人物表会漏掉节奏与历史处境。译名应统一对照。<strong>推荐语：</strong> 适合慢读一个家族怎样记住又遗忘自己，先追踪一条线索，已经足以进入作品。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li><a href="https://en.wikipedia.org/wiki/One_Hundred_Years_of_Solitude" target="_blank" rel="noopener noreferrer">作品、出版与主要主题</a>：作品身份与背景。</li><li><a href="https://www.gradesaver.com/one-hundred-years-of-solitude" target="_blank" rel="noopener noreferrer">GradeSaver 作品导读</a>：可按分章导读与手中译本对照。</li><li><a href="https://www.nobelprize.org/prizes/literature/1982/marquez/lecture/" target="_blank" rel="noopener noreferrer">马尔克斯诺贝尔文学奖演讲</a>：了解作家对拉丁美洲经验的表达，不将演讲直接等同于小说含义。</li></ul><p><a href="./../overview#humanities">返回书单总览</a></p>',27)])])}const b=e(o,[["render",n]]);export{u as __pageData,b as default};
